-- Reports historical data; no account, permission or two-step setting changes.
-- Rollback: restore reports_people_rows/reports_options from 0027/0028 (with later people-ID filter),
-- revoke the new history endpoint and revert Reports UI. Keep all historical rows and milestones.
CREATE OR REPLACE FUNCTION public.reports_login_range_complete(_from date,_to date) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT _from >= DATE '2026-09-14' AND _to >= _from AND NOT (_from <= DATE '2026-11-24' AND _to >= DATE '2026-11-15'); $$;
REVOKE ALL ON FUNCTION public.reports_login_range_complete(date,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.reports_login_range_complete(date,date) TO service_role;
CREATE OR REPLACE FUNCTION public.reports_login_history() RETURNS TABLE(id uuid,actor_id uuid,created_at timestamptz,action text,detail jsonb,user_agent text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT DISTINCT ON (e.actor_id,COALESCE(e.sign_in_session_id::text,NULLIF(e.detail->>'session_id',''),e.created_at::text)) e.id,e.actor_id,e.created_at,e.action,e.detail,e.user_agent
 FROM public.talent_audit_log e WHERE e.action='login'
 ORDER BY e.actor_id,COALESCE(e.sign_in_session_id::text,NULLIF(e.detail->>'session_id',''),e.created_at::text),e.created_at,e.id; $$;
REVOKE ALL ON FUNCTION public.reports_login_history() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reports_login_history() TO service_role;
DO $patch$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.reports_people_rows(date,date,jsonb,timestamptz)'::regprocedure);
 d:=replace(d,'FROM public.talent_audit_log e CROSS JOIN bounds b WHERE e.action=''login''','FROM public.reports_login_history() e CROSS JOIN bounds b WHERE e.action=''login''');
 d:=replace(d,'WHEN a.registered_at IS NULL OR (a.cutoff::timestamp AT TIME ZONE ''Africa/Johannesburg'')-public.sign_in_capture_started_at()<interval ''30 days''','WHEN a.registered_at IS NULL OR NOT public.reports_login_range_complete(a.cutoff-29,a.cutoff)');
 d:=replace(d,'a.start_at>=public.sign_in_capture_started_at() capture_complete','public.reports_login_range_complete(_from,a.cutoff) capture_complete');
 IF position('min(p.created_at)) registered_at' in d)=0 THEN
 d:=replace(d,'(SELECT min(i.accepted_at) FROM invitations i WHERE i.email=lower(btrim(p.email)) AND i.typ=''agency_staff'' AND i.accepted_at<b.end_at) registered_at','COALESCE((SELECT min(i.accepted_at) FROM invitations i WHERE i.email=lower(btrim(p.email)) AND i.typ=''agency_staff'' AND i.accepted_at<b.end_at),min(p.created_at)) registered_at');
 d:=replace(d,'(SELECT min(i.accepted_at) FROM invitations i WHERE i.email=lower(btrim(t.email)) AND i.typ=''talent'' AND i.accepted_at<b.end_at) registered_at','COALESCE((SELECT min(i.accepted_at) FROM invitations i WHERE i.email=lower(btrim(t.email)) AND i.typ=''talent'' AND i.accepted_at<b.end_at),p.created_at) registered_at');
 END IF; EXECUTE d;
END $patch$;
CREATE OR REPLACE FUNCTION public.reports_options() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN
 IF NOT public.reports_can('view_reports') THEN RAISE EXCEPTION 'REPORT_ACCESS_DENIED: Reports are available to authorised administrators only.' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('agencies',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'is_test',is_test) ORDER BY name,id) FROM public.agencies),'[]'::jsonb),'launch_date',(SELECT value->>'launch_date' FROM public.platform_settings WHERE key='launch'),
 'first_date',(SELECT min(first_at) FROM (SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date AS first_at FROM public.profiles UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.agencies UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.agency_invitations UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.independent_talent_invitations UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.talent_invitations UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.talent_private_documents UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.talent_shared_documents UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.loved_one_shares UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.agency_billing_docs UNION ALL SELECT (min(paid_on))::date FROM public.agency_invoice_payments UNION ALL SELECT (min(accepted_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.legal_acceptances UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.agency_talent_links UNION ALL SELECT (min(created_at) AT TIME ZONE 'Africa/Johannesburg')::date FROM public.talent_audit_log) dates),
 'first_login',(SELECT min(created_at) FROM public.reports_login_history()),'capture_started_at',public.sign_in_capture_started_at(),'contact_started_at',public.sign_in_capture_started_at(),'as_of',now(),'role',(SELECT role FROM public.reports_access WHERE user_id=auth.uid()),'joined_months',COALESCE((SELECT jsonb_agg(month_key ORDER BY month_key DESC) FROM (SELECT DISTINCT to_char((r->>'registered_at')::timestamptz AT TIME ZONE 'Africa/Johannesburg','YYYY-MM') month_key FROM public.reports_people_rows(DATE '1900-01-01',current_date,'{"accounts":"all","account_type":"all","talent":"all","source":"all","status":"any","agencies":[],"stage":"all","activity":"all"}',now()) r WHERE r->>'registered_at' IS NOT NULL) m),'[]'::jsonb)); END $$;
